import { Icon, ICON_MAP } from "../../atoms/Icon";
import { HealthSourceBadge } from "../health/HealthSourceBadge";
import type { ReadinessMetric } from "./today-readiness";

export type ReadinessStatProps = {
  metric: ReadinessMetric;
};

export function ReadinessStat({ metric }: ReadinessStatProps) {
  return (
    <div className="flex-1 min-w-0">
      <div className="flex items-baseline gap-1">
        <span className="text-[20px] font-bold tabular-nums text-ink-strong">
          {metric.value}
        </span>
        {metric.trend !== undefined && (
          <span className="inline-flex items-center gap-px text-[11px] font-medium tabular-nums text-ink-muted">
            <Icon icon={ICON_MAP.arrowUp} size="xs" color="inherit" />
            {metric.trend}
          </span>
        )}
      </div>
      <div className="text-[11px] font-semibold uppercase tracking-wide text-ink-muted mt-px">
        {metric.label}
      </div>
      {metric.source !== undefined && (
        <div className="mt-0.5">
          <HealthSourceBadge
            sourceBridgeId={metric.source}
            usedFallback={metric.usedFallback}
          />
        </div>
      )}
    </div>
  );
}
